code.cpp:
class Solution {
public:
    int uniquePaths(int m, int n) {
        // dp[j] = ways to reach cell in current row, column j
        vector<int> dp(n, 1);               // first row: only right moves
        for (int i = 1; i < m; ++i) {       // iterate remaining rows
            for (int j = 1; j < n; ++j) {
                dp[j] += dp[j - 1];         // ways from top + left
            }
        }
        return dp[n - 1];
    }
};
